<?php
declare(strict_types=1);
require dirname(__DIR__) . '/app/bootstrap.php';
$slug=trim($_GET['slug']??'');$stmt=db()->prepare("SELECT * FROM products WHERE slug=? AND status='published' LIMIT 1");$stmt->execute([$slug]);$product=$stmt->fetch();
if(!$product){http_response_code(404);exit('محصول پیدا نشد.');}
$images=db()->prepare('SELECT image_path,alt_text FROM product_images WHERE product_id=? ORDER BY is_primary DESC,sort_order');$images->execute([$product['id']]);$images=$images->fetchAll();
$cats=db()->prepare('SELECT c.name,c.slug FROM categories c JOIN product_categories pc ON pc.category_id=c.id WHERE pc.product_id=? AND c.is_active=1');$cats->execute([$product['id']]);$cats=$cats->fetchAll();
$siteName=setting('site_name','Crivit Iran');$siteLogo=setting('site_logo','');
?><!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($product['name'])?> | <?=e($siteName)?></title><meta name="description" content="<?=e($product['summary']??'')?>"><link rel="stylesheet" href="/assets/style.css"></head><body class="storefront">
<div class="topline"><div class="topline-inner"><span>تجهیزات ورزشی و لوازم ماجراجویی</span><span>انتخاب حرفه‌ای، تجربه خرید مطمئن</span></div></div>
<header class="store-header"><a class="brand" href="/"><?php if($siteLogo):?><img class="brand-logo" src="<?=e($siteLogo)?>" alt="<?=e($siteName)?>"><?php else:?><span class="brand-mark">C</span><?php endif?><span><?=e($siteName)?><small>SPORT & OUTDOOR</small></span></a><form class="search" action="/" method="get"><button aria-label="جستجو">⌕</button><input name="q" placeholder="جستجوی محصولات..."></form><div class="header-actions"><a href="/admin/login.php"><span class="action-icon">♙</span><span>حساب کاربری</span></a></div></header>
<nav class="main-nav"><div class="nav-inner"><a class="nav-home" href="/">صفحه اصلی</a><a href="/#categories">دسته‌بندی‌ها</a><a href="/#products">همه محصولات</a></div></nav>
<main class="store-main"><div class="listing-heading"><span>جزئیات محصول</span><h1><?=e($product['name'])?></h1></div><section class="product-detail"><div class="gallery"><?php foreach($images as $image):?><img src="<?=e($image['image_path'])?>" alt="<?=e($image['alt_text']??$product['name'])?>"><?php endforeach?><?php if(!$images):?><div class="image-placeholder">CRIVIT</div><?php endif?></div><div class="product-description"><div class="section-kicker">CRIVIT IRAN · SPORT & OUTDOOR</div><h1><?=e($product['name'])?></h1><p><?=e($product['summary']??'')?></p><?php if($product['sale_price']!==null):?><p class="old-price"><del><?=number_format((float)$product['price'])?> تومان</del></p><?php endif?><h2><?=number_format((float)($product['sale_price']??$product['price']))?> تومان</h2><p><?=nl2br(e($product['description']??''))?></p><p class="stock-label <?=((int)$product['stock_quantity']>0?'available':'unavailable')?>"><?=((int)$product['stock_quantity']>0?'موجود در انبار':'در حال حاضر ناموجود')?></p><div class="category-tags"><?php foreach($cats as $c):?><a href="/category.php?slug=<?=rawurlencode($c['slug'])?>"><?=e($c['name'])?></a><?php endforeach?></div></div></section></main>
